edits.newText:
export function extensionArgs(
	options: Pick<
		OpenOptions,
		"loadExtension" | "selectorDir" | "keepExtensions" | "headless"
	>,
): string[] {
	const dirs = [options.loadExtension, options.selectorDir].filter(
		(dir): dir is string => !!dir,
	);
	if (dirs.length === 0) return options.headless ? ["--disable-extensions"] : [];
	const loaded = dirs.join(",");
	const args = [`--load-extension=${loaded}`];
	if (!options.keepExtensions) args.push(`--disable-extensions-except=${loaded}`);
	return args;
}

/**
 * Locate the Dev Selector unpacked build: the newer of `.output/chrome-mv3` and
 * `.output/chrome-mv3-dev` (a dev rebuild repacks whichever one WXT chose).
 */
export function resolveDevSelectorDir(root: string): string {
	const candidates = ["chrome-mv3", "chrome-mv3-dev"].map((name) =>
		join(root, ".output", name),
	);
	let newest: { dir: string; mtime: number } | undefined;
	for (const dir of candidates) {
		const mtime = statSync(join(dir, "manifest.json"), {
			throwIfNoEntry: false,
		})?.mtimeMs;
		if (mtime !== undefined && (!newest || mtime > newest.mtime))
			newest = { dir, mtime };
	}
	if (!newest)
		throw new Error(
			`Dev Selector build not found: expected ${candidates.join(" or ")}`,
		);
	return newest.dir;
}

